import org.jetbrains.kotlin.gradle.ExperimentalWasmDsl

plugins {
    alias(libs.plugins.kotlinMultiplatform)
}

/**
 * The runtime that code generated by the WebIDL compiler (build-logic/webidl-compiler) calls into: dictionary
 * factories build JS objects with [com.cdodi.webidl.runtime.createJsObject], suspend wrappers await promises with
 * [com.cdodi.webidl.runtime.await]. Every bindings module (`:webgpu`, `:webaudio`) depends on it; nothing here knows
 * any particular spec.
 */
kotlin {
    @OptIn(ExperimentalWasmDsl::class)
    wasmJs {
        browser {
            testTask {
                useKarma {
                    useChromeHeadless()
                }
            }
        }
    }

    compilerOptions {
        optIn.add("kotlin.js.ExperimentalWasmJsInterop")
    }

    sourceSets {
        wasmJsMain.dependencies {
            api(libs.kotlinx.coroutines.core)
        }
        wasmJsTest.dependencies {
            implementation(libs.kotlin.test)
            implementation(libs.kotlinx.coroutines.test)
        }
    }
}
